-- The audit_log table starts empty; the server appends signed, hash-chained entries.
-- Quick check:
SELECT 'users' AS tbl, COUNT(*) AS n_rows FROM users UNION ALL SELECT 'departments', COUNT(*) FROM departments
UNION ALL SELECT 'resources', COUNT(*) FROM resources UNION ALL SELECT 'volunteers', COUNT(*) FROM volunteers
UNION ALL SELECT 'disaster_reports', COUNT(*) FROM disaster_reports UNION ALL SELECT 'response_tasks', COUNT(*) FROM response_tasks
UNION ALL SELECT 'shelters', COUNT(*) FROM shelters;
